insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('logical-reasoning', 'Logical Reasoning', 'Pattern detection, deduction, sequences and abstract reasoning — measured the way GRE and LSAT logic sections do.', 'Logical Reasoning measures how you detect patterns and draw valid conclusions from stated premises. The assessment has two parts: abstract pattern recognition (shape, color, rotation, quantity and spectrum sequences) and deductive reasoning (syllogisms and conditional logic, including recognizing when a conclusion only might be true rather than must be true).', 'git-branch', (select id from assessment_categories where key = 'logical'), ('standard_questionnaire')::assessment_engine_type, ('medium')::assessment_difficulty, 15, 15, false, ('free')::assessment_access, ('published')::assessment_status)
