insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'logical-reasoning'), 'overall', 0, 30, 'Developing', 'Basic logical reasoning abilities. Pattern recognition and deductive inference are still forming, with frequent difficulty distinguishing valid conclusions from plausible-sounding but unsupported ones.', ARRAY['Practice simple pattern-completion puzzles daily to build sequence recognition', 'Study the difference between valid syllogisms and common fallacies like affirming the consequent', 'Work through logic puzzles slowly, writing out each premise before concluding']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'logical-reasoning'), 'overall', 31, 50, 'Average', 'Moderate logical reasoning abilities. You can solve straightforward pattern and deduction problems but struggle with multi-step chains or subtler invalid-inference traps.', ARRAY['Practice multi-step syllogisms involving three or more premises', 'Time yourself on pattern sequences to build speed alongside accuracy', convert_from(decode('Rm9jdXMgb24gZGlzdGluZ3Vpc2hpbmcgJ211c3QgYmUgdHJ1ZScgZnJvbSAnbWlnaHQgYmUgdHJ1ZScgY29uY2x1c2lvbnM=', 'base64'), 'UTF8')]::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'logical-reasoning'), 'overall', 51, 70, 'Strong', 'Good logical reasoning abilities. You solve most pattern-recognition and deductive problems with consistent accuracy, occasionally missing more subtle or multi-layered items.', ARRAY['Challenge yourself with abstract reasoning puzzles that combine two changing attributes at once', 'Practice conditional logic chains (if-then-therefore) with nested conditions', 'Seek out advanced syllogism sets that include invalid-argument distractors']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'logical-reasoning'), 'overall', 71, 85, 'Very Strong', 'Strong logical reasoning abilities. You excel at identifying patterns and drawing valid conclusions, handling most deductive traps and multi-attribute sequences correctly.', ARRAY['Tackle competition-style logic puzzles and advanced abstract reasoning sets', 'Explore formal logic notation to deepen understanding of validity vs. soundness']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'logical-reasoning'), 'overall', 86, 100, 'Exceptional', 'Outstanding logical reasoning abilities. You demonstrate superior pattern recognition and deductive thinking skills, consistently identifying valid conclusions and complex sequence rules.', ARRAY['Pursue advanced study in formal logic, discrete mathematics, or algorithmic problem solving', 'Apply your reasoning strengths to real-world analytical or strategic decision-making roles']::text[], NULL, 5);
